create table if not exists public.ils_test_synthetic_professional_auth_evidence (evidence_id uuid primary key default gen_random_uuid(), provisioning_id uuid not null references public.ils_test_synthetic_professional_auth_provisioning(id) on delete restrict, auth_user_id uuid not null, authenticated_user_id uuid not null, run_id uuid not null default gen_random_uuid(), environment text not null default 'TEST', provenance_class text not null default 'REAL_AUTHENTICATED', binding_verified boolean not null, eligibility_verified boolean not null, assignment_created boolean not null default false, service_request_created boolean not null default false, work_item_created boolean not null default false, created_at timestamptz not null default now()); alter table public.ils_test_synthetic_professional_auth_evidence enable row level security; create or replace function public.ils_test_capture_professional_auth_proof() returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v_uid uuid:=auth.uid(); v_p record; v_trust boolean; v_cap boolean; v_id uuid; begin if coalesce(auth.role(),'')<>'authenticated' or v_uid is null then raise exception 'authenticated_user_required'; end if; select * into v_p from public.ils_test_synthetic_professional_auth_provisioning where auth_user_id=v_uid and synthetic_code='TEST_PROFESSIONAL_A' limit 1; if not found then raise exception 'professional_auth_binding_not_found'; end if; select exists(select 1 from public.ils_associate_trust_profiles t where t.user_id=v_uid and t.associate_id='TEST_PROFESSIONAL_A' and t.role_type='PROFESSIONAL_ASSOCIATE' and t.profile_status='ACTIVE' and t.identity_verified and t.qualification_verified and t.professional_registration_verified and t.capability_verified) into v_trust; select exists(select 1 from public.ils_associate_capabilities c where c.user_id=v_uid and c.role_type='PROFESSIONAL_ASSOCIATE' and c.capability_code='TEST_AUTH_ONLY' and c.status='VERIFIED' and c.verified_at is not null) into v_cap; if not v_trust or not v_cap then raise exception 'professional_eligibility_not_ready'; end if; if exists(select 1 from public.ils_professional_work_items w where w.professional_user_id=v_uid) or exists(select 1 from public.ils_professional_work_assignment_links l where l.professional_user_id=v_uid) then raise exception 'assignment_state_already_present'; end if; insert into public.ils_test_synthetic_professional_auth_evidence(provisioning_id,auth_user_id,authenticated_user_id,binding_verified,eligibility_verified) values(v_p.id,v_uid,v_uid,true,true) returning evidence_id into v_id; return jsonb_build_object('ok',true,'evidence_id',v_id,'run_id',(select run_id from public.ils_test_synthetic_professional_auth_evidence where evidence_id=v_id),'auth_user_id',v_uid,'authenticated_user_id',v_uid,'provenance_class','REAL_AUTHENTICATED','assignment_created',false,'service_request_created',false,'work_item_created',false,'environment','TEST'); end; $$;